// The conductor. One place decides what happens to a lead next, across every channel.
// Without this, email and LinkedIn run as two separate habits and a prospect gets a
// connection request the same morning as a break-up email.
const DEFAULT_CADENCE = [
  { day: 0,  channel: 'email',    action: 'opener' },
  { day: 2,  channel: 'linkedin', action: 'view_profile' },
  { day: 4,  channel: 'email',    action: 'follow_up_1' },
  { day: 6,  channel: 'linkedin', action: 'connect' },
  { day: 9,  channel: 'call',     action: 'call_attempt' },
  { day: 12, channel: 'email',    action: 'break_up' }
];

let cadence = DEFAULT_CADENCE;
if ($env.CADENCE_JSON) {
  try { cadence = JSON.parse($env.CADENCE_JSON); } catch (e) {
    throw new Error('CADENCE_JSON is not valid JSON: ' + String(e.message));
  }
}

const CAPS = {
  email: Number($env.DAILY_SEND_CAP || 80),
  linkedin: Math.min(Number($env.LI_DAILY_CAP || 20), 25),
  call: Number($env.DAILY_CALL_CAP || 15)
};

const MIN_CONFIDENCE = Number($env.MIN_CONFIDENCE || 70);
const today = new Date();
const todayStr = today.toISOString().slice(0, 10);

// Business days only. A cadence that counts weekends lands the follow-up on a Sunday.
const businessDaysBetween = (fromIso) => {
  const start = new Date(fromIso);
  if (isNaN(start.getTime())) return 0;
  let count = 0;
  const cursor = new Date(start.getTime());
  while (cursor < today) {
    cursor.setDate(cursor.getDate() + 1);
    const dow = cursor.getDay();
    if (dow !== 0 && dow !== 6) count++;
  }
  return count;
};

const dropped = { suppressed: 0, replied: 0, finished: 0, not_due: 0, no_channel: 0, low_confidence: 0, over_cap: 0 };
const due = [];

for (const item of $input.all()) {
  const lead = item.json;
  const stage = String(lead.stage || '').trim();

  if (stage === 'suppressed') { dropped.suppressed++; continue; }
  if (['replied', 'booked'].indexOf(stage) !== -1) { dropped.replied++; continue; }

  const step = Number(lead.cadence_step || 0);
  if (step >= cadence.length) { dropped.finished++; continue; }

  const plan = cadence[step];
  const startedAt = lead.cadence_started_at || lead.updated_at || lead.enriched_at || '';

  // A lead with no start date is entering the cadence today at step 0.
  const elapsed = startedAt ? businessDaysBetween(startedAt) : 0;
  if (startedAt && elapsed < Number(plan.day)) { dropped.not_due++; continue; }

  if (plan.channel === 'email') {
    if (!lead.email) { dropped.no_channel++; continue; }
    if (Number(lead.confidence || 0) < MIN_CONFIDENCE) { dropped.low_confidence++; continue; }
  }
  if (plan.channel === 'linkedin' && !lead.linkedin_url) { dropped.no_channel++; continue; }
  if (plan.channel === 'call' && !lead.phone) { dropped.no_channel++; continue; }

  due.push({ lead: lead, plan: plan, step: step });
}

// Best leads first, then apply a separate cap per channel.
due.sort((a, b) => Number(b.lead.fit_score || 0) - Number(a.lead.fit_score || 0));

const used = { email: 0, linkedin: 0, call: 0 };
const out = [];

for (const entry of due) {
  const ch = entry.plan.channel;
  if (used[ch] >= CAPS[ch]) { dropped.over_cap++; continue; }
  used[ch]++;

  out.push({ json: Object.assign({}, entry.lead, {
    channel: ch,
    action: entry.plan.action,
    cadence_step: entry.step,
    next_step: entry.step + 1,
    cadence_started_at: entry.lead.cadence_started_at || todayStr,
    task_date: todayStr,
    caps: CAPS,
    used: used,
    dropped: dropped
  })});
}

// Nothing due: return nothing. The lanes and the summary simply do not run, which is
// the right kind of quiet - a daily post saying 'zero touches' trains people to ignore it.
return out;

// Advance the cadence for everyone we queued, in one write.
const touched = $('decide the next touch').all();
const now = new Date().toISOString();

return touched.map((item) => ({ json: {
  lead_id: item.json.lead_id,
  cadence_step: item.json.next_step,
  cadence_started_at: item.json.cadence_started_at,
  last_channel: item.json.channel,
  last_action: item.json.action,
  updated_at: now
}}));

// One line per lane, plus why the rest were skipped.
const first = $('decide the next touch').first().json;
const used = first.used || { email: 0, linkedin: 0, call: 0 };
const caps = first.caps || {};
const d = first.dropped || {};

const total = used.email + used.linkedin + used.call;

const lines = [
  ':twisted_rightwards_arrows: *Cadence ' + first.task_date + '* - ' + total + ' touches queued',
  '  email ' + used.email + '/' + caps.email + '   linkedin ' + used.linkedin + '/' + caps.linkedin + '   calls ' + used.call + '/' + caps.call,
  '',
  '_Skipped: ' + (d.not_due || 0) + ' not due, ' + (d.replied || 0) + ' already replying, ' + (d.finished || 0) + ' finished the sequence, ' + (d.no_channel || 0) + ' missing that channel, ' + (d.low_confidence || 0) + ' low confidence, ' + (d.suppressed || 0) + ' suppressed, ' + (d.over_cap || 0) + ' held by a cap._'
];

return [{ json: { text: lines.join('\n') } }];
